/**
 * costi_per_tipologia.ts
 * Civiqa OpenCore — Costi Parametrici per Tipologia di Intervento
 *
 * Generated: 2026-05-23
 * Source: cba_mop_costi_per_tipologia_intervento.xlsx + cba_mop_costi_parametrici.xlsx
 * Reference: mop_albero_v2.ts (categorie di intervento)
 *
 * Ogni record mappa una categoria di intervento (C###) ai suoi:
 *   - costo base (min / max / med) per nuova realizzazione
 *   - unità di misura del costo
 *   - percentuali di aggiustamento per ciascuna tipologia di intervento
 *   - note metodologiche, fonte principale e fonti secondarie
 *
 * Records: 264
 *
 * Logica DOCFAP:
 *   costo_tipologia = val_med × (tipologia.pct_med / 100)
 *   range_min = val_min × (tipologia.pct_min / 100)
 *   range_max = val_max × (tipologia.pct_max / 100)
 */

// ── Enum Tipologie ──

export type TipologiaIntervento =
  | "NUOVA_REALIZZAZIONE"
  | "RISTRUTTURAZIONE"
  | "RISTRUTTURAZIONE_CON_EE"
  | "MANUTENZIONE_STRAORD_EE"
  | "MANUTENZIONE_ORDINARIA"
  | "RESTAURO"
  | "RECUPERO"
  | "AMPLIAMENTO_POTENZIAMENTO"
  | "AMMODERNAMENTO_TECNOLOGICO"
  | "DEMOLIZIONE"
  | "LAVORI_SOCIALMENTE_UTILI"
  | "ALTRO";

export const TIPOLOGIA_LABELS: Record<TipologiaIntervento, string> = {
  NUOVA_REALIZZAZIONE: "Nuova realizzazione",
  RISTRUTTURAZIONE: "Ristrutturazione",
  RISTRUTTURAZIONE_CON_EE: "Ristrutturazione con efficientamento energetico",
  MANUTENZIONE_STRAORD_EE: "Manutenzione straordinaria con efficientamento energetico",
  MANUTENZIONE_ORDINARIA: "Manutenzione ordinaria",
  RESTAURO: "Restauro",
  RECUPERO: "Recupero",
  AMPLIAMENTO_POTENZIAMENTO: "Ampliamento o potenziamento",
  AMMODERNAMENTO_TECNOLOGICO: "Ammodernamento tecnologico e laboratoriale",
  DEMOLIZIONE: "Demolizione",
  LAVORI_SOCIALMENTE_UTILI: "Lavori socialmente utili",
  ALTRO: "Altro",
};

// ── Interfaces ──

export interface TipologiaPct {
  /** Codice tipologia (enum key) */
  code: TipologiaIntervento;
  /** Percentuale minima rispetto al costo base nuova realizzazione */
  pct_min: number;
  /** Percentuale massima */
  pct_max: number;
  /** Percentuale media (pct_min + pct_max) / 2 */
  pct_med: number;
}

export interface CostoPerTipologia {
  /** Codice categoria di intervento MOP (C###) */
  cat_code: string;
  /** Label categoria da mop_albero_v2.ts */
  cat_label: string;
  /** Nome tipologia MOP dal file Excel */
  tipologia_mop: string;
  /** Descrizione originale del costo base */
  costo_base_raw: string;
  /** Unità di misura del costo (€/mq, €/km, €/UBA, ecc.) */
  udm: string;
  /** Valore minimo del range di costo base (nuova realizzazione) */
  val_min: number;
  /** Valore massimo del range di costo base (nuova realizzazione) */
  val_max: number;
  /** Valore medio calcolato: (val_min + val_max) / 2 */
  val_med: number;
  /** Percentuali di aggiustamento per ogni tipologia di intervento applicabile */
  tipologie: TipologiaPct[];
  /** Note specifiche per tipologia di intervento */
  note_intervento: string;
  /** Fonte principale dei dati di costo */
  fonte_principale: string;
  /** Fonti secondarie */
  fonti_secondarie: string;
  /** Note metodologiche sull'applicazione */
  note_metodologiche: string;
}

