// ── Helper: lookup + calcolo ──

/**
 * Cerca i record di costo per una data categoria di intervento.
 * Può restituire più record se la stessa categoria ha più voci nel file sorgente.
 */
export function getCostiByCategory(catCode: string): CostoPerTipologia[] {
  return COSTI_PER_TIPOLOGIA.filter(r => r.cat_code === catCode);
}

/**
 * Dato un record e una tipologia, calcola il costo aggiustato.
 * Restituisce null se la tipologia non è applicabile alla categoria.
 */
export function calcolaCostoTipologia(
  record: CostoPerTipologia,
  tipologia: TipologiaIntervento
): { val_min: number; val_max: number; val_med: number; udm: string } | null {
  const tip = record.tipologie.find(t => t.code === tipologia);
  if (!tip) return null;
  return {
    val_min: Math.round(record.val_min * tip.pct_min / 100),
    val_max: Math.round(record.val_max * tip.pct_max / 100),
    val_med: Math.round(record.val_med * tip.pct_med / 100),
    udm: record.udm,
  };
}

/**
 * Restituisce tutte le tipologie applicabili per una data categoria,
 * con i costi calcolati per ciascuna.
 */
export function getTipologieApplicabili(catCode: string): Array<{
  tipologia: TipologiaIntervento;
  label: string;
  val_min: number;
  val_max: number;
  val_med: number;
  udm: string;
  fonte_principale: string;
  fonti_secondarie: string;
  note_metodologiche: string;
}> {
  const records = getCostiByCategory(catCode);
  if (records.length === 0) return [];
  const rec = records[0]; // primary record
  return rec.tipologie.map(tip => ({
    tipologia: tip.code,
    label: TIPOLOGIA_LABELS[tip.code],
    val_min: Math.round(rec.val_min * tip.pct_min / 100),
    val_max: Math.round(rec.val_max * tip.pct_max / 100),
    val_med: Math.round(rec.val_med * tip.pct_med / 100),
    udm: rec.udm,
    fonte_principale: rec.fonte_principale,
    fonti_secondarie: rec.fonti_secondarie,
    note_metodologiche: rec.note_metodologiche,
  }));
}
